!> Set selected aerosol physical and optical parameters with native fields.
module selected_aerosol_parameter_fields_mod
  use iso_fortran_env, only: int32, int64, real64
  use yoeaeratm, only: teaeratm
  use yoeaerlid, only: teaerlid
  use yoeaermap, only: teaermap
  use yoeaersnk, only: teaersnk
  use yoeaersrc, only: teaersrc
  use yoeaervol, only: teaervol
  use yoedbug, only: tedbug
  implicit none
  private
  public :: aerosol_optical_parameter_record, aerosol_parameter_control_record
  public :: initialize_selected_aerosol_parameter_fields
  public :: initialize_aerosol_physical_parameter_fields, initialize_aerosol_optical_parameter_fields
  !> Counts and scheme controls are dimensionless; NINDAT is the model date.
  !! NSSSSS is seconds after midnight. The checked caller supplies this input.
  type :: aerosol_parameter_control_record
    integer(int32) :: naero, nactaero, naermacc
    logical :: leso4his
    integer(int32) :: nindat, nsssss
  end type
  !> Own the original 68 named optical tables in declaration order.
  !! Arrays contain the original spectral coefficients in Fortran order.
  !! Unwritten fly-ash tables retain their incoming values for a later producer.
  !! The compiler owns storage; no module-state image supplies values.
  type :: aerosol_optical_parameter_record
    real(real64) :: alf_bc(20)
    real(real64) :: asy_bc(20)
    real(real64) :: omg_bc(20)
    real(real64) :: rali_bc(20)
    real(real64) :: alf_dd(9, 20)
    real(real64) :: asy_dd(9, 20)
    real(real64) :: omg_dd(9, 20)
    real(real64) :: rali_dd(9, 20)
    real(real64) :: alf_om(12, 20)
    real(real64) :: asy_om(12, 20)
    real(real64) :: omg_om(12, 20)
    real(real64) :: rali_om(12, 20)
    real(real64) :: alf_ss(12, 20, 9)
    real(real64) :: asy_ss(12, 20, 9)
    real(real64) :: omg_ss(12, 20, 9)
    real(real64) :: rali_ss(12, 20, 9)
    real(real64) :: alf_su(12, 20)
    real(real64) :: asy_su(12, 20)
    real(real64) :: omg_su(12, 20)
    real(real64) :: rali_su(12, 20)
    real(real64) :: alf_ni(12, 20, 2)
    real(real64) :: asy_ni(12, 20, 2)
    real(real64) :: omg_ni(12, 20, 2)
    real(real64) :: rali_ni(12, 20, 2)
    real(real64) :: alf_soa(12, 20, 2)
    real(real64) :: asy_soa(12, 20, 2)
    real(real64) :: omg_soa(12, 20, 2)
    real(real64) :: rali_soa(12, 20, 2)
    real(real64) :: alf_am(12, 20)
    real(real64) :: asy_am(12, 20)
    real(real64) :: omg_am(12, 20)
    real(real64) :: rali_am(12, 20)
    real(real64) :: alfs_bc(14)
    real(real64) :: asys_bc(14)
    real(real64) :: omgs_bc(14)
    real(real64) :: alfs_dd(3, 14)
    real(real64) :: asys_dd(3, 14)
    real(real64) :: omgs_dd(3, 14)
    real(real64) :: alfs_fa(14)
    real(real64) :: asys_fa(14)
    real(real64) :: omgs_fa(14)
    real(real64) :: alfs_om(12, 14)
    real(real64) :: asys_om(12, 14)
    real(real64) :: omgs_om(12, 14)
    real(real64) :: alfs_ss(12, 14, 3)
    real(real64) :: asys_ss(12, 14, 3)
    real(real64) :: omgs_ss(12, 14, 3)
    real(real64) :: alfs_su(12, 14)
    real(real64) :: asys_su(12, 14)
    real(real64) :: omgs_su(12, 14)
    real(real64) :: alfl_bc(16)
    real(real64) :: asyl_bc(16)
    real(real64) :: omgl_bc(16)
    real(real64) :: alfl_dd(3, 16)
    real(real64) :: asyl_dd(3, 16)
    real(real64) :: omgl_dd(3, 16)
    real(real64) :: alfl_fa(16)
    real(real64) :: asyl_fa(16)
    real(real64) :: omgl_fa(16)
    real(real64) :: alfl_om(12, 16)
